def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_last = my[-1]
    op_last = op[-1]

    # Always-defect / always-cooperate detection
    op_def_total = n - op.count('C')
    if op_def_total == 0:
        return 'C'

    # Lookback windows
    w3 = op[-3:]
    w5 = op[-5:]
    w10 = op[-10:] if n >= 10 else op
    w20 = op[-20:] if n >= 20 else op
    d3 = w3.count('D')
    d5 = w5.count('D')
    d10 = w10.count('D')
    c10 = len(w10) - d10
    len10 = len(w10)

    # If opponent never defects over last 10 and we've seen enough, cooperate
    if len10 >= 8 and d10 == 0:
        return 'C'

    # If opponent nearly always defects recently, defect but occasionally test
    if len10 >= 6 and d10 >= len10 - 1:
        if n % 9 == 0 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Estimate recent cooperation rate
    coop_recent = c10 / len10 if len10 else 0.0

    # Late-game exploitation: last 5 rounds, defect if opponent is cooperative enough
    remaining = 100 - n
    if remaining <= 5 and remaining > 0:
        if coop_recent >= 0.5:
            return 'D'
        if d3 == 0:
            return 'D'
        if rng.random() < 0.5:
            return 'D'
        return 'D'

    # Punish sustained defection
    if d5 >= 4:
        return 'D' if rng.random() < 0.9 else 'C'
    if d3 >= 3:
        return 'D'

    # Establish early cooperation
    if n <= 3:
        return 'C'

    # If opponent just defected
    if op_last == 'D':
        # If we cooperated and they defected (exploitation)
        if my_last == 'C':
            # Immediate retaliation, but forgiveness if recent rate high
            if coop_recent >= 0.7 and d5 <= 2:
                if rng.random() < 0.4:
                    return 'C'
                return 'D'
            return 'D'
        else:
            # We both defected recently - try to break the DD cycle
            if my_last == 'D' and op_last == 'D':
                # Reset attempt if recent cooperation exists elsewhere
                if coop_recent >= 0.4:
                    if rng.random() < 0.5:
                        return 'C'
                    return 'D'
                if rng.random() < 0.2:
                    return 'C'
                return 'D'
            return 'D'

    # Opponent just cooperated
    if op_last == 'C':
        # If we defected last, return to cooperation (rebuild trust)
        if my_last == 'D':
            return 'C'
        # Otherwise cooperate, but probe very occasionally when in a long CC streak
        if n < 90 and coop_recent >= 0.85 and n % 23 == 0:
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    return 'C'
